<body>
<script src="https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.min.js"></script>
<script src="https://cdn.jsdelivr.net/npm/three@0.160.0/examples/js/controls/OrbitControls.js"></script>
<script>
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1a1f2b);
scene.fog = new THREE.Fog(0x1a1f2b, 60, 160);

const camera = new THREE.PerspectiveCamera(50, innerWidth/innerHeight, 0.1, 300);
camera.position.set(28, 22, 34);

const renderer = new THREE.WebGLRenderer({antialias:true});
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio,2));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
document.body.appendChild(renderer.domElement);

const controls = new THREE.OrbitControls(camera, renderer.domElement);
controls.target.set(0, 6, 0);
controls.enableDamping = true;
controls.dampingFactor = 0.06;
controls.maxPolarAngle = Math.PI/2.05;
controls.minDistance = 12;
controls.maxDistance = 90;

scene.add(new THREE.HemisphereLight(0xbfd4ff, 0x3a4a3f, 0.55));
const sun = new THREE.DirectionalLight(0xfff2d8, 1.1);
sun.position.set(30, 40, 18);
sun.castShadow = true;
sun.shadow.mapSize.set(2048, 2048);
sun.shadow.camera.left = -55; sun.shadow.camera.right = 55;
sun.shadow.camera.top = 55; sun.shadow.camera.bottom = -55;
sun.shadow.camera.far = 140;
scene.add(sun);
const fill = new THREE.DirectionalLight(0xd8e8ff, 0.25);
fill.position.set(-25, 15, -20);
scene.add(fill);

const mat = (c, e=0) => new THREE.MeshLambertMaterial({color:c, emissive:e});
const M = {
  stone:  mat(0x8d939a), stoneDark: mat(0x6b7076), wood: mat(0x7a4a2b),
  woodDark: mat(0x5a3520), roof: mat(0x2f4f4f), roofTrim: mat(0xc9b370),
  leaf:   mat(0x4a7a3a), leafDark: mat(0x3a5f2e), trunk: mat(0x5a4030),
  water:  mat(0x2a5a7a), sakura: mat(0xf2b8cc), sakuraDeep: mat(0xe08fae),
  lantern:mat(0xb8bcc2), glow: mat(0xffe9b0, 0xffe9b0), grass: mat(0x5f8a4a),
  path:   mat(0xb0a288), gold: mat(0xd4af5a), red: mat(0xa83232)
};

const voxels = new THREE.Group();
scene.add(voxels);
const geo = new THREE.BoxGeometry(1,1,1);

function put(x,y,z,m){
  const v = new THREE.Mesh(geo, m);
  v.position.set(x,y,z);
  v.castShadow = true; v.receiveShadow = true;
  voxels.add(v);
}

// ---------- ground ----------
const G = 60;
for(let x=-G; x<=G; x++) for(let z=-G; z<=G; z++){
  const d = Math.max(Math.abs(x), Math.abs(z));
  if(d > G) continue;
  const r = Math.sqrt(x*x+z*z);
  let m = M.grass;
  if(r > 46) m = M.leafDark;
  put(x, -1, z, m);
}

// stone path from bridge to pagoda
for(let z=-14; z<=14; z++){
  put(0, -0.5, z, M.path);
  if(z % 3 !== 0){ put(1, -0.5, z, M.path); put(-1, -0.5, z, M.path); }
}

// ---------- pagoda ----------
